from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel


class SourceApiAssociationSummary(SdkBaseModel):
    association_id: Optional[str] = Field(default=UNSET, alias="associationId")
    """The ID generated by the AppSync service for the source API association."""

    association_arn: Optional[str] = Field(default=UNSET, alias="associationArn")
    """The Amazon Resource Name (ARN) of the source API association."""

    source_api_id: Optional[str] = Field(default=UNSET, alias="sourceApiId")
    """The ID of the AppSync source API."""

    source_api_arn: Optional[str] = Field(default=UNSET, alias="sourceApiArn")
    """The Amazon Resource Name (ARN) of the AppSync Source API."""

    merged_api_id: Optional[str] = Field(default=UNSET, alias="mergedApiId")
    """The ID of the AppSync Merged API."""

    merged_api_arn: Optional[str] = Field(default=UNSET, alias="mergedApiArn")
    """The Amazon Resource Name (ARN) of the AppSync Merged API."""

    description: Optional[str] = UNSET
    """The description field."""


class SourceApiAssociationSummaryDict(TypedDict):
    association_id: NotRequired[str]
    association_arn: NotRequired[str]
    source_api_id: NotRequired[str]
    source_api_arn: NotRequired[str]
    merged_api_id: NotRequired[str]
    merged_api_arn: NotRequired[str]
    description: NotRequired[str]
